{
  "name": "opencode-mkdir",
  "version": "0.2.0",
  "description": "OpenCode TUI plugin: /mkdir creates a folder and moves the current session into it",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "tui",
    "mkdir",
    "slash-command"
  ],
  "license": "MIT",
  "author": "igorovh",
  "homepage": "https://github.com/igorovh/opencode-mkdir#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/igorovh/opencode-mkdir.git"
  },
  "bugs": {
    "url": "https://github.com/igorovh/opencode-mkdir/issues"
  },
  "type": "module",
  "private": true,
  "files": [
    "tui.ts",
    "src",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    "./tui": "./src/tui.ts"
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.5"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "2.3.0",
    "@types/bun": "1.4.4",
    "typescript": "7.0.2"
  }
}
